"use client"

import * as React from "react"
import { cn } from "cn"

import { Separator } from "@tecton/react/components/separator"
import { Meter } from "@tecton/react/tecton/meter"

import type { DesignPoint, Metric, MetricCategory } from "../data"

type ComparisonListProps = React.ComponentProps<"div"> & {
  metrics: Metric[]
  designs: DesignPoint[]
  /** Ids of designs to show (defaults to all). */
  selected?: string[]
}

/**
 * Stacked comparison of the selected designs per metric: a bold total row
 * followed by category breakdowns, each rendered as a coloured bar.
 */
function ComparisonList({
  className,
  metrics,
  designs,
  selected,
  ...props
}: ComparisonListProps) {
  const visible = selected
    ? designs.filter((design) => selected.includes(design.id))
    : designs

  return (
    <div
      data-slot="comparison-list"
      className={cn("flex flex-col gap-6", className)}
      {...props}
    >
      {metrics.map((metric) => (
        <section key={metric.id} className="flex flex-col gap-3">
          <ComparisonGroup
            title={metric.label}
            emphasis
            metric={metric}
            category={metric.total}
            designs={visible}
          />
          {metric.categories.map((category) => (
            <React.Fragment key={category.id}>
              <Separator emphasis="subtle" />
              <ComparisonGroup
                title={category.label}
                metric={metric}
                category={category}
                designs={visible}
              />
            </React.Fragment>
          ))}
        </section>
      ))}
    </div>
  )
}

function ComparisonGroup({
  title,
  emphasis = false,
  metric,
  category,
  designs,
}: {
  title: string
  emphasis?: boolean
  metric: Metric
  category: MetricCategory
  designs: DesignPoint[]
}) {
  return (
    <div data-slot="comparison-group" className="flex flex-col gap-1.5">
      <h4 className={cn("text-xs font-medium", emphasis && "text-sm")}>
        {title}
      </h4>
      <div className="flex flex-col gap-1">
        {designs.map((design) => {
          const entry = category.values[design.id]
          if (!entry) return null
          return (
            <ComparisonBar
              key={design.id}
              design={design}
              value={entry.value}
              range={entry.range}
              max={metric.max}
              format={metric.format}
            />
          )
        })}
      </div>
    </div>
  )
}

function ComparisonBar({
  design,
  value,
  range,
  max,
  format,
}: {
  design: DesignPoint
  value: number
  range?: [number, number] | undefined
  max: number
  format: (value: number) => string
}) {
  return (
    <div
      data-slot="comparison-bar"
      className="grid grid-cols-[1fr_auto] items-center gap-3"
    >
      <Meter
        aria-label={`${design.name}: ${format(value)}`}
        value={value}
        min={0}
        max={max}
        segments={1}
        size="sm"
        color="custom"
        style={{ "--meter-fill": design.color } as React.CSSProperties}
      />
      <span className="min-w-20 text-end font-mono text-xs tabular-nums">
        {format(value)}
        {range && (
          <span className="text-muted-foreground"> –{format(range[1])}</span>
        )}
      </span>
    </div>
  )
}

export { ComparisonList, ComparisonGroup, ComparisonBar }
export type { ComparisonListProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import {
  CartesianGrid,
  Cell,
  ReferenceLine,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts"

import {
  ChartContainer,
  ChartTooltip,
  type ChartConfig,
} from "@tecton/react/components/chart"

import { getAxis, riskLabel } from "../data"
import type { AxisOption, DesignPoint } from "../data"

type QuadrantChartProps = React.ComponentProps<"div"> & {
  designs: DesignPoint[]
  /** Ids of the highlighted designs; others are dimmed. */
  selected?: string[]
  /** Metric on the horizontal axis (cost by default). */
  xAxis?: AxisOption
  /** Metric on the vertical axis (risk by default). */
  yAxis?: AxisOption
  /** Axis titles; default to the axes' labels. */
  xLabel?: string
  yLabel?: string
}

/**
 * Bubble chart of two design metrics (cost vs risk by default) split into
 * four quadrants by reference lines at the mid-point of each axis. Bubble
 * area = plan days.
 */
function QuadrantChart({
  className,
  designs,
  selected,
  xAxis = getAxis("cost"),
  yAxis = getAxis("risk"),
  xLabel = xAxis.label,
  yLabel = yAxis.label,
  ...props
}: QuadrantChartProps) {
  const config = React.useMemo<ChartConfig>(
    () =>
      Object.fromEntries(
        designs.map((design) => [
          design.id,
          { label: design.name, color: design.color },
        ])
      ),
    [designs]
  )

  const [xMin, xMax] = xAxis.domain(
    designs.map((design) => design[xAxis.dataKey])
  )
  const [yMin, yMax] = yAxis.domain(
    designs.map((design) => design[yAxis.dataKey])
  )
  const xMid = (xMin + xMax) / 2
  const yMid = (yMin + yMax) / 2

  return (
    <ChartContainer
      data-slot="quadrant-chart"
      config={config}
      className={cn(
        "aspect-square w-full rounded-md bg-surface-alt/60",
        className
      )}
      {...props}
    >
      <ScatterChart margin={{ top: 24, right: 24, bottom: 24, left: 8 }}>
        <CartesianGrid strokeDasharray="2 4" />
        <XAxis
          type="number"
          dataKey={xAxis.dataKey}
          name={xLabel}
          domain={[xMin, xMax]}
          tickLine={false}
          axisLine={false}
          tickFormatter={xAxis.format}
          fontSize={10}
        />
        <YAxis
          type="number"
          dataKey={yAxis.dataKey}
          name={yLabel}
          domain={[yMin, yMax]}
          tickLine={false}
          axisLine={false}
          tickFormatter={yAxis.format}
          width={40}
          fontSize={10}
        />
        <ZAxis type="number" dataKey="planDays" range={[240, 900]} />
        <ReferenceLine
          x={xMid}
          stroke="var(--border-strong)"
          label={{
            value: `High ${yLabel.toLowerCase()}`,
            position: "insideTopLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
            dx: 6,
          }}
        />
        <ReferenceLine
          x={xMid}
          stroke="transparent"
          label={{
            value: `Low ${yLabel.toLowerCase()}`,
            position: "insideBottomLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
            dx: 6,
          }}
        />
        <ReferenceLine
          y={yMid}
          stroke="var(--border-strong)"
          label={{
            value: `Low ${xLabel.toLowerCase()}`,
            position: "insideBottomLeft",
            fill: "var(--muted-foreground)",
            fontSize: 10,
          }}
        />
        <ReferenceLine
          y={yMid}
          stroke="transparent"
          label={{
            value: `High ${xLabel.toLowerCase()}`,
            position: "insideBottomRight",
            fill: "var(--muted-foreground)",
            fontSize: 10,
          }}
        />
        <ChartTooltip
          cursor={false}
          content={({ active, payload }) => {
            const point = payload[0]?.payload as DesignPoint | undefined
            if (!active || !point) return null
            return <QuadrantTooltip point={point} />
          }}
        />
        <Scatter data={designs} isAnimationActive={false}>
          {designs.map((design) => {
            const dimmed = selected && !selected.includes(design.id)
            return (
              <Cell
                key={design.id}
                fill={design.color}
                fillOpacity={dimmed ? 0.15 : 0.55}
                stroke={design.color}
                strokeOpacity={dimmed ? 0.4 : 1}
                strokeWidth={design.isRecommended ? 2 : 1}
              />
            )
          })}
        </Scatter>
      </ScatterChart>
    </ChartContainer>
  )
}

function QuadrantTooltip({ point }: { point: DesignPoint }) {
  return (
    <div className="grid min-w-36 gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl">
      <div className="flex items-center gap-1.5 font-medium">
        <span
          className="size-2.5 shrink-0 rounded-[2px]"
          style={{ background: point.color }}
        />
        {point.name}
        {point.isRecommended && (
          <span className="ms-auto text-[0.625rem] text-muted-foreground">
            Recommended
          </span>
        )}
      </div>
      <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-0.5 text-muted-foreground">
        <dt>Cost</dt>
        <dd className="text-end font-mono text-foreground tabular-nums">
          ${point.costRange[0]}–{point.costRange[1]}M
        </dd>
        <dt>Risk</dt>
        <dd className="text-end font-mono text-foreground tabular-nums">
          {point.risk}% · {riskLabel(point.risk)}
        </dd>
        <dt>Plan days</dt>
        <dd className="text-end font-mono text-foreground tabular-nums">
          {point.planDays}d
        </dd>
      </dl>
    </div>
  )
}

export { QuadrantChart, QuadrantTooltip }
export type { QuadrantChartProps }

export type DesignPoint = {
  id: string
  name: string
  /** Chart series colour token, e.g. `var(--chart-1)`. */
  color: string
  /** Total cost in $M (mid estimate). */
  cost: number
  costRange: [number, number]
  /** Aggregate risk score 0–100. */
  risk: number
  riskRange: [number, number]
  /** Bubble size — plan days. */
  planDays: number
  isRecommended?: boolean
}

export type MetricValue = {
  value: number
  range?: [number, number]
}

export type MetricCategory = {
  id: string
  label: string
  values: Record<string, MetricValue>
}

export type Metric = {
  id: "cost" | "risk"
  label: string
  /** Formats a value for display. */
  format: (value: number) => string
  /** Upper bound used to scale the bars. */
  max: number
  total: MetricCategory
  categories: MetricCategory[]
}

