export type AxisId = "cost" | "risk" | "days"

/** A metric the quadrant chart can plot on either axis. */
export type AxisOption = {
  id: AxisId
  label: string
  /** The `DesignPoint` field plotted on the axis. */
  dataKey: "cost" | "risk" | "planDays"
  /** Tick label for a value. */
  format: (value: number) => string
  /** Axis range for the plotted values. */
  domain: (values: number[]) => [number, number]
}

/** Pads the value range by `pad` and rounds it out to multiples of `step`. */
function paddedDomain(pad: number, step: number) {
  return (values: number[]): [number, number] => [
    Math.max(0, Math.floor((Math.min(...values) - pad) / step) * step),
    Math.ceil((Math.max(...values) + pad) / step) * step,
  ]
}

export const axisOptions: [AxisOption, ...AxisOption[]] = [
  {
    id: "cost",
    label: "Cost",
    dataKey: "cost",
    format: (value) => `$${value}M`,
    domain: paddedDomain(15, 10),
  },
  {
    id: "risk",
    label: "Risk",
    dataKey: "risk",
    format: (value) => `${value}%`,
    // A 0–100 score: the whole scale, so 50 splits the quadrants.
    domain: () => [0, 100],
  },
  {
    id: "days",
    label: "Plan days",
    dataKey: "planDays",
    format: (value) => `${value}d`,
    domain: paddedDomain(5, 5),
  },
]

export function getAxis(id: string): AxisOption {
  return axisOptions.find((option) => option.id === id) ?? axisOptions[0]
}

export function riskLabel(value: number): string {
  if (value >= 67) return "High"
  if (value >= 34) return "Medium"
  return "Low"
}

"use client"

import * as React from "react"
import { cn } from "cn"
import { CrownIcon, PanelRightIcon, PanelRightOpenIcon } from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@tecton/react/components/select"
import { Chip, ChipGroup, ChipList } from "@tecton/react/tecton/chip"
import {
  Panel,
  PanelActions,
  PanelContent,
  PanelHeader,
  PanelTitle,
} from "@tecton/react/tecton/panel"

import { ComparisonList } from "./components/comparison-list"
import { QuadrantChart } from "./components/quadrant-chart"
import { axisOptions, designs as allDesigns, getAxis, metrics } from "./data"
import type { AxisId, DesignPoint } from "./data"

/** The axis names the Select shows for each value. */
const axisItems = axisOptions.map((option) => ({
  value: option.id,
  label: option.label,
}))

type CostVsRiskPanelProps = Omit<
  React.ComponentProps<typeof Panel>,
  "children"
> & {
  designs?: DesignPoint[]
  defaultSelected?: string[]
  onCollapse?: () => void
}

/**
 * Cost vs risk panel — quadrant bubble chart, legend chips that toggle the
 * compared designs, and a bar-list breakdown of cost and risk categories.
 */
function CostVsRiskPanel({
  className,
  designs = allDesigns,
  defaultSelected = ["initial", "liner"],
  onCollapse,
  ...props
}: CostVsRiskPanelProps) {
  const [selected, setSelected] = React.useState<string[]>(defaultSelected)
  const [xAxis, setXAxis] = React.useState<AxisId>("cost")
  const [yAxis, setYAxis] = React.useState<AxisId>("risk")

  return (
    <Panel
      data-slot="cost-vs-risk-panel"
      className={cn("h-full", className)}
      {...props}
    >
      <PanelHeader>
        <PanelTitle className="text-base">
          {selected.length} Selected
        </PanelTitle>
        <PanelActions>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Collapse panel"
            onClick={onCollapse}
          >
            <PanelRightIcon className="rtl:rotate-180" />
          </Button>
        </PanelActions>
      </PanelHeader>
      <PanelContent className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center justify-end gap-2 text-xs text-muted-foreground">
          <span>Compare</span>
          <Select
            items={axisItems}
            value={xAxis}
            onValueChange={(axis: AxisId | null) => {
              if (axis) setXAxis(axis)
            }}
          >
            <SelectTrigger
              aria-label="X axis"
              variant="filled"
              size="sm"
              className="w-28"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {axisOptions.map((option) => (
                <SelectItem
                  key={option.id}
                  value={option.id}
                  disabled={option.id === yAxis}
                >
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <span>and</span>
          <Select
            items={axisItems}
            value={yAxis}
            onValueChange={(axis: AxisId | null) => {
              if (axis) setYAxis(axis)
            }}
          >
            <SelectTrigger
              aria-label="Y axis"
              variant="filled"
              size="sm"
              className="w-28"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {axisOptions.map((option) => (
                <SelectItem
                  key={option.id}
                  value={option.id}
                  disabled={option.id === xAxis}
                >
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <QuadrantChart
          designs={designs}
          selected={selected}
          xAxis={getAxis(xAxis)}
          yAxis={getAxis(yAxis)}
        />

        <ChipGroup
          data-slot="cost-vs-risk-legend"
          aria-label="Designs"
          selectionMode="multiple"
          disallowEmptySelection
          value={selected}
          onValueChange={(values) =>
            // Kept in the order of the designs, not the order of the clicks.
            setSelected(
              designs
                .filter((design) => values.includes(design.id))
                .map((design) => design.id)
            )
          }
        >
          <ChipList>
            {designs.map((design) => {
              const active = selected.includes(design.id)
              return (
                <Chip
                  key={design.id}
                  value={design.id}
                  label={design.name}
                  size="md"
                  appearance={active ? "solid" : "outline"}
                >
                  <span
                    aria-hidden
                    className="size-2 rounded-[2px]"
                    style={{
                      background: design.color,
                      opacity: active ? 1 : 0.6,
                    }}
                  />
                  {design.name}
                  {design.isRecommended && <CrownIcon className="size-3" />}
                </Chip>
              )
            })}
          </ChipList>
        </ChipGroup>

        <ComparisonList
          metrics={metrics}
          designs={designs}
          selected={selected}
        />
      </PanelContent>
    </Panel>
  )
}

/** Route-ready page: the panel docked on the right of an empty canvas. */
export default function CostVsRiskPanelPage() {
  const [open, setOpen] = React.useState(true)

  return (
    <div
      data-slot="cost-vs-risk-panel-page"
      className="flex h-svh w-full bg-background text-foreground"
    >
      <div className="hidden min-w-0 flex-1 items-center justify-center p-6 text-sm text-muted-foreground md:flex">
        Well design comparison
      </div>
      {open ? (
        <div className="flex h-full w-full max-w-md shrink-0 flex-col border-s border-border-subtle">
          <CostVsRiskPanel
            variant="flat"
            className="rounded-none border-0"
            onCollapse={() => setOpen(false)}
          />
        </div>
      ) : (
        <div className="flex h-full shrink-0 flex-col border-s border-border-subtle p-2">
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Expand cost vs risk panel"
            onClick={() => setOpen(true)}
          >
            <PanelRightOpenIcon className="rtl:rotate-180" />
          </Button>
        </div>
      )}
    </div>
  )
}

export { CostVsRiskPanel, QuadrantChart, ComparisonList }
export { designs, metrics, axisOptions, getAxis, riskLabel } from "./data"
export type { CostVsRiskPanelProps }
export type {
  AxisId,
  AxisOption,
  DesignPoint,
  Metric,
  MetricCategory,
  MetricValue,
} from "./data"
